WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_x_average'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '年龄与平均数综合', 'kp-age-x-average', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "年龄与平均数综合"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "N年前团队的平均年龄，并不是今天的平均年龄减去 N。因为有人可能是中途加入或出生的！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、致命陷阱"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "时光倒流陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“团队 5 人现在平均 30 岁，5 年前平均多少岁？” 正常人觉得是 25。但如果团队里有个新员工今年才 3 岁，5 年前他不存在！5 年前只有 4 个人参与平均！必须用现在的总和 150 减去 5 个人的时间流逝倒推。"}]}]}]}$$ AS jsonb), NULL, '年龄与平均数综合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "年龄与平均数综合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_x_average", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
